<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/includes/app.php';
require_once dirname(__DIR__).'/includes/admin-auth.php';
require_once dirname(__DIR__).'/includes/blog/blog-functions.php';
$user=mg_require_admin_page_any(['admin.blog.view','admin.blog.manage']);$canManage=mg_admin_permission_user_has($user,'admin.blog.manage');$pdo=mg_db();$schema=mg_blog_schema_ready($pdo);$notice='';$errors=[];$editId=max(0,(int)($_GET['edit']??0));function mg_blog_category_unique_slug(PDO $pdo,string $slug,int $exclude=0): string{$base=mg_blog_slugify($slug,'category');$cand=$base;$i=2;while(true){$sql='SELECT id FROM blog_categories WHERE slug=?';$p=[$cand];if($exclude>0){$sql.=' AND id<>?';$p[]=$exclude;}$s=$pdo->prepare($sql.' LIMIT 1');$s->execute($p);if(!$s->fetch(PDO::FETCH_ASSOC)){return $cand;}$cand=substr($base,0,130).'-'.$i++;}}
if($_SERVER['REQUEST_METHOD']==='POST'){if(!$canManage){mg_admin_page_forbidden('admin.blog.manage');}elseif(!mg_verify_csrf((string)($_POST['csrf_token']??''))){$errors[]='Security token expired. Refresh and try again.';}elseif(!$schema['ready']){$errors[]='Blog SQL migration is required before managing categories.';}else{$action=(string)($_POST['action']??'save');$id=max(0,(int)($_POST['category_id']??0));if($action==='toggle'&&$id>0){$active=!empty($_POST['is_active'])?1:0;$s=$pdo->prepare('UPDATE blog_categories SET is_active=?,updated_at=NOW() WHERE id=?');$s->execute([$active,$id]);$notice=$active?'Category activated.':'Category deactivated.';}else{$name=trim((string)($_POST['name']??''));$desc=trim((string)($_POST['description']??''));$sort=(int)($_POST['sort_order']??100);$active=!empty($_POST['is_active'])?1:0;if($name===''){$errors[]='Category name is required.';}$slug=mg_blog_category_unique_slug($pdo,trim((string)($_POST['slug']??''))?:$name,$id);if(!$errors){if($id>0){$s=$pdo->prepare('UPDATE blog_categories SET name=?,slug=?,description=?,sort_order=?,is_active=?,updated_at=NOW() WHERE id=?');$s->execute([$name,$slug,$desc!==''?$desc:null,$sort,$active,$id]);$notice='Category updated.';}else{$s=$pdo->prepare('INSERT INTO blog_categories (name,slug,description,sort_order,is_active) VALUES (?,?,?,?,?)');$s->execute([$name,$slug,$desc!==''?$desc:null,$sort,$active]);$notice='Category created.';}}}}}$categories=$schema['ready']?mg_blog_categories($pdo,false):[];$form=['id'=>0,'name'=>'','slug'=>'','description'=>'','sort_order'=>100,'is_active'=>1];if($editId>0&&$schema['ready']){$s=$pdo->prepare('SELECT id,name,slug,description,sort_order,is_active FROM blog_categories WHERE id=? LIMIT 1');$s->execute([$editId]);$editing=$s->fetch(PDO::FETCH_ASSOC);if($editing){$form=array_merge($form,$editing);}}if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'save')==='save'&&$notice===''){$form=array_merge($form,$_POST);}$page_title='Blog Categories | Microgifter Admin';$page_section='account';$header_mode='account';$page_body_class='mg-admin-blog-page';$page_styles=['/assets/css/admin-shell.css','/assets/css/admin-blog.css','/assets/css/admin-blog-categories.css'];$adminActive='blog';require dirname(__DIR__).'/includes/header.php';
?>
<section class="mg-app-shell mg-admin-app"><?php require dirname(__DIR__).'/includes/admin-sidebar.php'; ?><div class="mg-app-workspace mg-admin-workspace"><main class="mg-admin-blog-shell"><header class="mg-admin-blog-hero is-editor"><div><a class="mg-admin-blog-back" href="/admin/blog-posts.php">← Blog manager</a><span class="mg-eyebrow">Content Studio</span><h1>Blog categories</h1><p>Manage public category pages for Microgifter articles.</p></div><div class="mg-admin-blog-actions"><a class="mg-btn mg-btn-soft" href="/blog.php" target="_blank" rel="noopener">View public blog</a><a class="mg-btn mg-btn-ghost" href="/admin/blog-posts.php">All posts</a></div></header><?php if(!$schema['ready']): ?><section class="mg-admin-blog-alert"><strong>SQL migration required.</strong><span>Run <code>database/microgifter_blog_module.sql</code>.</span></section><?php endif; ?><?php if($notice!==''): ?><section class="mg-admin-blog-alert is-success"><strong>Saved.</strong><span><?= mg_e($notice) ?></span></section><?php endif; ?><?php foreach($errors as $m): ?><section class="mg-admin-blog-alert is-error"><strong>Fix needed.</strong><span><?= mg_e((string)$m) ?></span></section><?php endforeach; ?><section class="mg-admin-blog-category-layout"><form class="mg-admin-blog-side-card mg-admin-blog-category-form" method="post" action="/admin/blog-categories.php<?= (int)$form['id']>0?'?edit='.(int)$form['id']:'' ?>"><?= mg_csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="category_id" value="<?= (int)$form['id'] ?>"><h2><?= (int)$form['id']>0?'Edit category':'Create category' ?></h2><label>Name<input type="text" name="name" maxlength="120" value="<?= mg_e((string)$form['name']) ?>" required></label><label>Slug<input type="text" name="slug" maxlength="140" value="<?= mg_e((string)$form['slug']) ?>"></label><label>Description<textarea name="description" rows="5"><?= mg_e((string)$form['description']) ?></textarea></label><label>Sort order<input type="number" name="sort_order" value="<?= (int)$form['sort_order'] ?>"></label><label class="mg-admin-blog-check"><input type="checkbox" name="is_active" value="1" <?= !empty($form['is_active'])?'checked':'' ?>> Active public category</label><div class="mg-admin-blog-save-row"><button class="mg-btn mg-btn-primary" type="submit">Save category</button><a class="mg-btn mg-btn-ghost" href="/admin/blog-categories.php">New category</a></div></form><section class="mg-admin-blog-panel mg-admin-blog-category-list-panel"><?php if(!$schema['ready']): ?><div class="mg-admin-blog-empty"><h2>Category tables are not installed yet.</h2><p>Import the blog migration to manage categories.</p></div><?php elseif(!$categories): ?><div class="mg-admin-blog-empty"><h2>No categories yet.</h2><p>Create the first blog category.</p></div><?php else: ?><div class="mg-admin-blog-table-wrap"><table class="mg-admin-blog-table"><thead><tr><th>Category</th><th>Status</th><th>Sort</th><th>Public URL</th><th>Actions</th></tr></thead><tbody><?php foreach($categories as $cat): ?><tr><td><div class="mg-admin-blog-title-cell is-category"><span class="mg-admin-blog-thumb is-category"></span><div><strong><?= mg_e((string)$cat['name']) ?></strong><span><?= mg_e((string)$cat['slug']) ?></span><small><?= mg_e(mb_substr((string)($cat['description']??''),0,140)) ?></small></div></div></td><td><span class="mg-admin-blog-status <?= !empty($cat['is_active'])?'is-published':'is-archived' ?>"><?= !empty($cat['is_active'])?'active':'inactive' ?></span></td><td><?= (int)$cat['sort_order'] ?></td><td><a href="<?= mg_e(mg_blog_public_category_url($cat)) ?>" target="_blank" rel="noopener">Open</a></td><td><div class="mg-admin-blog-row-actions"><a href="/admin/blog-categories.php?edit=<?= (int)$cat['id'] ?>">Edit</a><?php if($canManage): ?><form method="post" action="/admin/blog-categories.php"><?= mg_csrf_field() ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="category_id" value="<?= (int)$cat['id'] ?>"><input type="hidden" name="is_active" value="<?= !empty($cat['is_active'])?'0':'1' ?>"><button type="submit"><?= !empty($cat['is_active'])?'Deactivate':'Activate' ?></button></form><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></section></main></div></section><?php require dirname(__DIR__).'/includes/footer.php'; ?>
